        const string Art="Assets/Unfin/Art/Region2V1";
        static void Check(bool value,string message){if(!value)throw new Exception("Region2: "+message);}
        static void Private(object target,string method,params object[] args)=>target.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(target,args);
        public static void Apply(){
            AssetDatabase.Refresh();
            var paths=Directory.GetFiles("Assets/Unfin/Resources/Region2","*.png",SearchOption.AllDirectories).Concat(Directory.GetFiles("Assets/Unfin/Resources/EnemyAnimations","*.png").Where(p=>{var id=Path.GetFileNameWithoutExtension(p);return id.StartsWith("R2")||"EFGH".Contains(id.Substring(0,1));}));
            foreach(var p in paths){var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.textureType=TextureImporterType.Default;ti.sRGBTexture=true;ti.alphaIsTransparency=true;ti.npotScale=TextureImporterNPOTScale.None;ti.mipmapEnabled=true;ti.wrapMode=TextureWrapMode.Clamp;ti.filterMode=FilterMode.Trilinear;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.Uncompressed;var web=ti.GetPlatformTextureSettings("WebGL");web.overridden=true;web.maxTextureSize=2048;web.format=p.Contains("Encounters")||p.Contains("EnemyAnimations")?TextureImporterFormat.DXT5:TextureImporterFormat.RGBA32;ti.SetPlatformTextureSettings(web);ti.SaveAndReimport();}
            EditorSceneManager.OpenScene(WorldPrototypeBuilder.ScenePath);var w=UnityEngine.Object.FindAnyObjectByType<WorldPrototype>();var data=JsonUtility.FromJson<WorldData>(w.mapJson.text);ApplyFar(data);RoomBackdropImporter.Apply(data);EditorSceneManager.SaveScene(w.gameObject.scene);AssetDatabase.SaveAssets();
        }
        static void ApplyFar(WorldData d){
            var material=AssetDatabase.LoadAssetAtPath<Material>(Art+"/Background.mat");var shader=Shader.Find("Unfin/Region2 Background");Check(shader!=null&&shader.isSupported,"background shader supported");if(material==null){material=new Material(shader);AssetDatabase.CreateAsset(material,Art+"/Background.mat");}material.shader=shader;
            string[] fields={"_Paper","_Graphite","_Wood","_Root"};int width=d.width-d.regionX;for(int i=0;i<4;i++){string p=Art+"/"+"EFGH"[i]+"-wall.png";var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.textureType=TextureImporterType.Default;ti.wrapMode=TextureWrapMode.Clamp;ti.npotScale=TextureImporterNPOTScale.None;ti.filterMode=FilterMode.Trilinear;ti.mipmapEnabled=true;ti.maxTextureSize=1024;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();material.SetTexture(fields[i],AssetDatabase.LoadAssetAtPath<Texture2D>(p));}
            var rooms=d.rooms.Where(r=>r.r==2).ToArray();var texture=new Texture2D(width+1,d.height+1,TextureFormat.RGBA32,false,true);var colors=new Color[(width+1)*(d.height+1)];for(int y=0;y<=d.height;y++)for(int x=0;x<=width;x++){float[] distances={float.PositiveInfinity,float.PositiveInfinity,float.PositiveInfinity,float.PositiveInfinity};foreach(var r in rooms){int k="EFGH".IndexOf(r.z,StringComparison.Ordinal);float dx=Mathf.Max(r.x-(x+d.regionX),0,x+d.regionX-r.x-r.w),dy=Mathf.Max(r.y-y,0,y-r.y-r.h);distances[k]=Mathf.Min(distances[k],Mathf.Sqrt(dx*dx+dy*dy));}float near=distances.Min(),total=0;var c=new Color();for(int k=0;k<4;k++){c[k]=Mathf.SmoothStep(0,1,1-(distances[k]-near)/4);total+=c[k];}colors[y*(width+1)+x]=c/total;}texture.SetPixels(colors);texture.Apply();File.WriteAllBytes(Art+"/ZoneWeights.png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(Art+"/ZoneWeights.png",ImportAssetOptions.ForceUpdate);var zi=(TextureImporter)AssetImporter.GetAtPath(Art+"/ZoneWeights.png");zi.sRGBTexture=false;zi.alphaIsTransparency=false;zi.alphaSource=TextureImporterAlphaSource.FromInput;zi.mipmapEnabled=false;zi.npotScale=TextureImporterNPOTScale.None;zi.textureCompression=TextureImporterCompression.Uncompressed;zi.wrapMode=TextureWrapMode.Clamp;zi.filterMode=FilterMode.Bilinear;zi.SaveAndReimport();material.SetTexture("_Zones",AssetDatabase.LoadAssetAtPath<Texture2D>(Art+"/ZoneWeights.png"));material.SetTexture("_OldRoot",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Unfin/Art/Region1BackgroundV3/D-root-wall.png"));material.SetVector("_Bounds",new Vector4(width,d.height,0,0));material.SetFloat("_Opacity",.72f);EditorUtility.SetDirty(material);
            const string name="World 2 - Painted wax back walls";var old=GameObject.Find(name);if(old!=null)UnityEngine.Object.DestroyImmediate(old);var go=GameObject.CreatePrimitive(PrimitiveType.Quad);go.name=name;UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());go.transform.position=new Vector3(d.regionX+width*.5f,-d.height*.5f,5);go.transform.localScale=new Vector3(width,d.height,1);var renderer=go.GetComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.sortingOrder=-100;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;
        }
        static WorldPrototype World(){EditorSceneManager.OpenScene(WorldPrototypeBuilder.ScenePath);var w=UnityEngine.Object.FindAnyObjectByType<WorldPrototype>();Private(w,"Awake");return w;}
        static MapMarker Marker(int index)=>UnityEngine.Object.FindObjectsByType<MapMarker>(FindObjectsSortMode.None).Single(m=>m.enemy&&m.sourceIndex==index);
        static void Advance(WorldPrototype w,PaperRegion2Encounter actor,float seconds){for(float t=0;t<seconds;t+=.005f){w.Progression.Tick(.005f,0,0);actor.Tick(.005f);}}
        public static void Validate(){
            Directory.CreateDirectory("Validation");var w=World();w.Progression.UseAbilityLocks=true;foreach(string ability in new[]{"walljump","cut","dash"})w.Progression.Grant(ability);Check(!w.Progression.Has("parry")&&!w.Progression.Has("climb"),"entry kit respects progression");
            Check(w.Data.rooms.Count(r=>r.r==2)==26,"26 authored rooms");Check(PaperEnemyAnimation.Manifest.enemies.Length==33,"33 species total");var regional=PaperEnemyAnimation.Manifest.enemies.Where(e=>e.id.StartsWith("R2")||"EFGH".Contains(e.id.Substring(0,1))).ToArray();Check(regional.Length==15&&regional.All(e=>e.clips.Length==3&&e.clips.All(c=>c.durations.Length==8)),"15 new species / 360 drawings");
            foreach(var p in PaperEnemyAnimation.Manifest.placements.Where(p=>p.sourceIndex>=51)){var m=Marker(p.sourceIndex);Check(PaperEnemyAnimation.Attach(m),"normal actor "+p.sourceIndex);Check(m.GetComponent<SpriteRenderer>().sprite!=null,"drawing installed");}
            var tm=Marker(69);Check(PaperRegion2Encounter.Attach(tm),"turtle override");var turtle=tm.GetComponent<PaperRegion2Encounter>();Check(tm.GetComponent<ExplorationEncounter>()==null,"no old elite receiver");
            w.Respawn(365,94);w.Simulate(.001f);w.Progression.Health=100;turtle.Tick(.001f);turtle.transform.position=new Vector3(366,-94,0);turtle.BeginPattern(0);Advance(w,turtle,.95f);Check(turtle.Staggered,"wall bait staggers turtle without parry");var target=tm.GetComponent<PaperAttackTarget>();for(int i=0;i<8;i++)target.ReceiveHit(1);Check(turtle.Dead&&!w.Progression.Has("parry"),"reward waits for death animation");Advance(w,turtle,1.5f);Check(w.Progression.Has("parry")&&!w.Progression.Has("climb"),"elite unlocks parry only");
            var km=Marker(91);PaperRegion2Encounter.Attach(km);var knight=km.GetComponent<PaperRegion2Encounter>();Check(knight.Health==45&&km.GetComponent<ExplorationEncounter>()==null,"45hp knight without old receiver");int projectilePeak=0;float[] movement=new float[4];int[] active=new int[4];for(int p=0;p<4;p++){w.Respawn(518,50);w.Simulate(.001f);w.Progression.Health=100;knight.Tick(.001f);var start=knight.transform.position;knight.BeginPattern(p);for(float t=0;t<1.7f;t+=.005f){knight.Tick(.005f);w.Progression.Tick(.005f,0,0);projectilePeak=Math.Max(projectilePeak,knight.LiveProjectiles);movement[p]=Math.Max(movement[p],Vector3.Distance(start,knight.transform.position));active[p]=Math.Max(active[p],knight.ActiveShapes);}}Check(active[0]>0&&active[2]>0&&active[3]>0&&projectilePeak>0,"four real knight attacks");Check(movement[2]>1&&movement[3]>1,"rush and slam physically move");
            w.Respawn(520,50);w.Simulate(.001f);w.Progression.Health=100;knight.Tick(.001f);knight.BeginPattern(0);Advance(w,knight,.5f);for(int i=0;i<3;i++){w.Progression.Parry();Advance(w,knight,.06f);if(i<2)Advance(w,knight,.29f);}Check(knight.Staggered,"three timed parries create earned opening");
            var receiver=km.GetComponent<PaperAttackTarget>();for(int i=0;i<23;i++)receiver.ReceiveHit(1);knight.Tick(.005f);Check(knight.Phase2&&w.HeatedPlatformCount>0,"phase2 heats real platforms");for(int i=0;i<22;i++)receiver.ReceiveHit(1);Check(knight.Dead&&w.HeatedPlatformCount==0,"death restores arena platforms");Advance(w,knight,2);Check(w.Progression.Has("climb")&&w.Progression.DefeatedEncounters.Contains(91),"knight death unlocks climb");w.Respawn(518,50);knight.Tick(.005f);Check(knight.Dead,"boss defeat persists across respawn");
            var fire=w.Data.pickups.First(p=>p.type=="brazier");Check(w.Progression.BrazierLit(fire),"brazier starts lit");w.Progression.ExtinguishBrazier(fire);Check(!w.Progression.BrazierLit(fire),"attack extinguishes fire");w.Progression.Tick(5.1f,0,0);Check(w.Progression.BrazierLit(fire),"fire returns after five seconds");
            foreach(var p in w.Data.pickups.Where(p=>p.type.StartsWith("sw_"))){var r=WorldPropPlacement.CollectionBox(p);var c=new Vector2(r.center.x,-r.center.y);var polygon=new[]{c+new Vector2(-1,-1),c+new Vector2(1,-1),c+new Vector2(1,1),c+new Vector2(-1,1)};w.Progression.AttackGate(polygon);Check(w.Progression.Collected(p),"attack fills pigment pot "+p.type);}Check(w.Progression.PigmentsReady,"three pigments unlock main route");
            Region2Story.ReadDiary(w);Check(w.Progression.Toast.Contains("유치"),"diary foreshadows knight");Region2Story.Talk(w);Check(w.Progression.Toast.Contains("덧칠")||w.Progression.Toast.Contains("부러져"),"post-boss resident dialogue");
            File.WriteAllText("Validation/region2-v1.json","{\"passed\":true,\"rooms\":26,\"zones\":4,\"newSpecies\":15,\"newMonsterDrawings\":360,\"normalPlacements\":42,\"turtleDrawings\":24,\"knightDrawings\":48,\"knightPatterns\":4,\"preParryEliteCounter\":true,\"tripleParryCounter\":true,\"realProjectiles\":true,\"heatedPlatforms\":true,\"deathAndRewards\":true,\"pigments\":true,\"story\":true}");Debug.Log("UNFIN_REGION2_OK 26 rooms / 15 new species / turtle / knight / story / progression");EditorSceneManager.OpenScene(WorldPrototypeBuilder.ScenePath);
        }
        static Vector2Int Spawn(WorldPrototype w,WorldArea r){if(r.n==20&&r.r==2)return new Vector2Int(518,50);if(r.n==10&&r.r==2)return new Vector2Int(379,94);Vector2Int best=new Vector2Int(r.x+2,r.y+r.h);float score=float.PositiveInfinity;for(int y=r.y+2;y<=r.y+r.h;y++)for(int x=r.x+1;x<r.x+r.w-1;x++){int tile=w.Motor.Get(x,y);if((tile!=1&&tile!=4&&tile!=16)||w.Motor.Get(x,y-1)!=0||w.Motor.Get(x,y-2)!=0)continue;float s=Mathf.Abs(x-r.x-r.w*.5f)+(r.y+r.h-y)*.3f;foreach(var e in w.Data.enemies)if(Mathf.Abs(e.tx-x)<3&&Mathf.Abs(e.floor-y)<2)s+=12;if(s<score){score=s;best=new Vector2Int(x,y);}}return best;}
        static void Capture(Camera camera,string path,int width=1280,int height=720){var rt=RenderTexture.GetTemporary(width,height,24);camera.targetTexture=rt;camera.aspect=(float)width/height;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(image);}
        public static void Render(){
            var w=World();Directory.CreateDirectory("Validation/region2-rooms");var start=typeof(MapMarker).GetMethod("Start",BindingFlags.NonPublic|BindingFlags.Instance);foreach(var m in UnityEngine.Object.FindObjectsByType<MapMarker>(FindObjectsSortMode.None))if(!m.enemy||m.sourceIndex>=51)start.Invoke(m,null);Region2GateVisual.Create(w);var player=w.player.GetComponentInChildren<PaperSpritePlayer>();PaperPlayerSurface.Apply(player.visual);string entries="";
            foreach(var r in w.Data.rooms.Where(r=>r.r==2)){var spawn=Spawn(w,r);w.worldCamera.orthographicSize=w.Data.orthographicSize;w.worldCamera.aspect=16f/9;w.Respawn(spawn.x,spawn.y);w.Motor.vx=0;w.Motor.vy=20;w.Motor.Move(.1f);Private(w,"SyncView");player.Tick(.001f);foreach(var d in UnityEngine.Object.FindObjectsByType<PaperDeviceVisual>(FindObjectsSortMode.None))d.Tick(0);foreach(var a in UnityEngine.Object.FindObjectsByType<PaperRegion2Encounter>(FindObjectsSortMode.None))a.Tick(0);foreach(var layer in UnityEngine.Object.FindObjectsByType<RoomBackdropLayer>(FindObjectsSortMode.None)){layer.Configure();layer.PositionForCamera();}var camera=w.worldCamera;camera.orthographicSize=w.Data.orthographicSize;float groundPx=360+(camera.transform.position.y+spawn.y)*360/camera.orthographicSize;Capture(camera,"Validation/region2-rooms/"+r.n.ToString("D2")+"-play.png");if(new[]{3,5,18,20}.Contains(r.n)){var actors=UnityEngine.Object.FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None).Where(a=>a.GetComponentInParent<MapMarker>()!=null&&a.GetComponentInParent<MapMarker>().enemy).ToArray();var enabled=actors.Select(a=>a.enabled).ToArray();foreach(var a in actors)a.enabled=false;Capture(camera,"Validation/region2-rooms/"+r.z+"-clean.png");for(int i=0;i<actors.Length;i++)actors[i].enabled=enabled[i];}camera.orthographicSize=Mathf.Max((r.h+2)*.5f,(r.w+2)*.5f/(16f/9));camera.transform.position=new Vector3(r.x+r.w*.5f,-r.y-r.h*.5f,-10);Capture(camera,"Validation/region2-rooms/"+r.n.ToString("D2")+"-room.png",960,540);if(entries.Length>0)entries+=",";entries+="{\"n\":"+r.n+",\"zone\":\""+r.z+"\",\"name\":\""+r.name+"\",\"w\":"+r.w+",\"h\":"+r.h+",\"groundPx\":"+groundPx.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"orthographicSize\":"+w.Data.orthographicSize.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"spawn\":\""+spawn.x+","+spawn.y+"\"}";}
            w.worldCamera.orthographicSize=w.Data.orthographicSize;w.Respawn(465,124);w.Motor.vx=0;w.Motor.vy=20;w.Motor.Move(.1f);Private(w,"SyncView");player.Tick(.001f);foreach(var d in UnityEngine.Object.FindObjectsByType<PaperDeviceVisual>(FindObjectsSortMode.None))d.Tick(0);Capture(w.worldCamera,"Validation/region2-rooms/resident-before.png");w.Progression.DefeatedEncounters.Add(91);w.Respawn(465,124);player.Tick(.001f);foreach(var d in UnityEngine.Object.FindObjectsByType<PaperDeviceVisual>(FindObjectsSortMode.None))d.Tick(.2f);w.worldCamera.orthographicSize=w.Data.orthographicSize;Capture(w.worldCamera,"Validation/region2-rooms/resident-after.png");File.WriteAllText("Validation/region2-rooms/rooms.json","{\"rooms\":["+entries+"]}");EditorSceneManager.OpenScene(WorldPrototypeBuilder.ScenePath);
        }
